pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number1,
        uint64 _timestamp1,
        uint256 _basefee1,
        bytes32 _hash1,
        uint64 _sequenceNumber1,
        bytes32 _batcherHash1,
        uint256 _l1FeeOverhead1,
        uint256 _l1FeeScalar1,
        uint64 _number2,
        uint64 _timestamp2,
        uint256 _basefee2,
        bytes32 _hash2,
        uint64 _sequenceNumber2,
        bytes32 _batcherHash2,
        uint256 _l1FeeOverhead2,
        uint256 _l1FeeScalar2
    ) public {
        vm.assume(_number1 != _number2);
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        c.setL1BlockValues(_number1, _timestamp1, _basefee1, _hash1, _sequenceNumber1, _batcherHash1, _l1FeeOverhead1, _l1FeeScalar1);
        vm.prank(depositor);
        c.setL1BlockValues(_number2, _timestamp2, _basefee2, _hash2, _sequenceNumber2, _batcherHash2, _l1FeeOverhead2, _l1FeeScalar2);
        assertTrue(c.number() == _number2);
    }
}

